// السجل الحالي القادم من جدول client_platforms
const platform = $('Loop Over Items').item.json;

if (!platform.id) {
  throw new Error('platform_id غير موجود');
}

const output = [];

for (const item of items) {
  const place = item.json;

  // بعض Actors تضع التقييمات داخل مصفوفة،
  // وبعضها يعيد كل تقييم كسجل مستقل
  let reviews =
    place.reviews ||
    place.reviewsData ||
    place.reviewData ||
    place.reviewsPersonalData ||
    [];

  if (!Array.isArray(reviews)) {
    reviews = [];
  }

  // إذا كان العنصر نفسه يمثل تقييمًا
  if (
    reviews.length === 0 &&
    (
      place.reviewId ||
      place.reviewText ||
      place.text ||
      place.rating ||
      place.stars
    )
  ) {
    reviews = [place];
  }

  for (let i = 0; i < reviews.length; i++) {
    const review = reviews[i];

    const reviewText =
      review.text ||
      review.reviewText ||
      review.textTranslated ||
      review.comment ||
      '';

    // تجاهل التقييمات التي لا تحتوي على نص
    if (!reviewText.trim()) {
      continue;
    }

    const reviewDate =
      review.publishedAtDate ||
      review.date ||
      review.publishedAt ||
      null;

    const reviewId =
      review.reviewId ||
      review.id ||
      review.reviewUrl ||
      `${platform.id}_${reviewDate || 'no-date'}_${i}_${reviewText.slice(0, 40)}`;

    const starsValue =
      review.stars ??
      review.rating ??
      review.reviewRating ??
      null;

    output.push({
      json: {
        // بيانات الربط
        branch_id: platform.branch_id,
        platform_id: platform.id,

        // بيانات تقييم Google
        review_id: String(reviewId),
        reviewer_name:
          review.name ||
          review.reviewerName ||
          review.userName ||
          null,

        stars:
          starsValue !== null && starsValue !== ''
            ? Number(starsValue)
            : null,

        review_text: reviewText.trim(),
        review_date: reviewDate,

        review_url:
          review.reviewUrl ||
          review.url ||
          platform.platform_url ||
          null,

        owner_reply:
          review.responseFromOwnerText ||
          review.ownerReply ||
          review.ownerResponse ||
          null,

        // حالة التحليل
        analysis_status: 'pending',

        // البيانات الأصلية القادمة من Apify
        raw_data: review
      }
    });
  }
}

const fetchFailed = items.some(({ json }) =>
  Boolean(json?.error || json?.errorDescription || json?.requestErrorMessages)
);

if (output.length === 0) {
  return [{ json: {
    fetch_succeeded: !fetchFailed,
    has_scraped_reviews: false,
    client_id: platform.client_id,
    branch_id: platform.branch_id ?? null,
    platform_id: platform.id
  } }];
}

return output.map(({ json }) => ({
  json: {
    ...json,
    fetch_succeeded: true,
    has_scraped_reviews: true
  }
}));

const batch = $('Create AI Batch').item.json;

let text =
  $json.output?.[0]?.content?.[0]?.text ||
  $json.message?.content ||
  $json.content?.[0]?.text ||
  $json.text ||
  '';

text = String(text)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

if (!text) {
  throw new Error('لم يتم العثور على نتيجة التحليل');
}

let parsed;

try {
  parsed = JSON.parse(text);
} catch (error) {
  throw new Error('نتيجة الذكاء الاصطناعي ليست JSON صالحًا');
}

if (!Array.isArray(parsed.results)) {
  throw new Error('الحقل results غير موجود أو ليس مصفوفة');
}

const reviews = batch.reviews || [];

const toBoolean = (value) => {
  if (value === true || value === 'true') return true;
  return false;
};

return parsed.results.map(result => {
  const sourceRecordId =
    result.source_record_id ??
    result.id;

  const originalReview = reviews.find(
    review => String(review.google_review_id) === String(sourceRecordId)
  );

  return {
    json: {
      client_id: batch.client_id,
      branch_id: batch.branch_id,
      platform_id: batch.platform_id,

      platform_name: 'google_maps',
      source_table: 'google_reviews',
      source_record_id: Number(sourceRecordId),

      external_id: originalReview?.review_id || null,

      sentiment: result.sentiment || 'neutral',

      category: Array.isArray(result.category)
        ? result.category
        : [result.category || 'أخرى'],

      severity: result.severity || 'low',

      needs_reply: toBoolean(result.needs_reply),
      is_sales_opportunity: toBoolean(result.is_sales_opportunity),
      is_complaint: toBoolean(result.is_complaint),

      suggested_reply: result.suggested_reply || null,
      reason: result.reason || null,
      analysis_summary: result.analysis_summary || null,

      analysis_status: 'completed',
      model_name: 'gpt-4o-mini',
      analyzed_at: new Date().toISOString()
    }
  };
});

// بيانات المنصة الحالية القادمة من client_platforms
const platform = $('Loop Over Items').item.json;

const reviews = items
  .filter(item => item.json.id && item.json.review_text)
  .map(item => ({
    // رقم السجل داخل جدول google_reviews
    google_review_id: item.json.id,

    // معرف التقييم الأصلي من Google
    review_id: item.json.review_id,

    reviewer_name: item.json.reviewer_name || null,
    stars: item.json.stars ?? null,
    review_text: item.json.review_text,
    review_date: item.json.review_date || null,

    branch_id: item.json.branch_id,
    platform_id: item.json.platform_id,

    // يؤخذ من سجل client_platforms
    client_id: platform.client_id
  }));

return [
  {
    json: {
      platform_name: 'google_maps',
      source_table: 'google_reviews',
      client_id: platform.client_id,
      branch_id: platform.branch_id,
      platform_id: platform.id,
      reviews
    }
  }
];
